/// Analyze a deck: geometry, model checks and program summary.
pub fn analyze(text: &str, store: &NgfStore, options: &ModelOptions) -> Result<Analysis, String> {
    let m = model(text, store, options)?;
    // Checked at the frequency the model was segmented for, or the deck's first.
    let first = m
        .segmented_for
        .and_then(|f| Frequency::from_mhz(f).ok())
        .or_else(|| m.program.as_ref().ok().and_then(|p| p.frequencies.first().copied()));
    let findings = lint_with(&m.geom, &m.lint_context(first))
        .into_iter()
        .map(|f| Finding {
            severity: match f.severity {
                Severity::Info => "info",
                Severity::Warning => "warning",
                Severity::Error => "error",
            },
            kind: f.kind,
            segment: f.segment,
            message: f.message,
        })
        .collect();
    let mut tags: Vec<i32> = m.geom.segments.iter().map(|s| s.tag).collect();
    tags.dedup();
    Ok(Analysis {
        segments: m
            .geom
            .segments
            .iter()
            .zip(&m.geom.origins)
            .enumerate()
            .map(|(i, (s, &origin))| SegmentView {
                auxiliary: m.is_auxiliary(i),
                a: [s.a.x, s.a.y, s.a.z],
                b: [s.b.x, s.b.y, s.b.z],
                radius: s.radius,
                tag: s.tag,
                origin,
            })
            .collect(),
        patches: m
            .geom
            .patches
            .iter()
            .map(|p| {
                let n = p.normal();
                PatchView {
                    outline: p.outline.iter().map(|q| [q.x, q.y, q.z]).collect(),
                    center: [p.center.x, p.center.y, p.center.z],
                    normal: [n.x, n.y, n.z],
                }
            })
            .collect(),
        ngf: NgfView {
            writes: m.program.as_ref().ok().and_then(|p| p.write_ngf.clone()),
            reads: m.base_name.clone(),
            base_segments: m.geom.base_segments,
            locked_mhz: m.base.as_ref().map(|b| b.frequency.mhz()),
            runs: m.runs,
        },
        wires: tags.len(),
        ground: m
            .program
            .as_ref()
            .map_or_else(|_| "?".into(), |p| nec_engine::ground_label(&p.ground)),
        has_ground: m
            .program
            .as_ref()
            .is_ok_and(|p| p.ground != GroundSpec::FreeSpace),
        frequencies_mhz: m
            .program
            .as_ref()
            .map(|p| p.frequencies.iter().map(|f| f.mhz()).collect())
            .unwrap_or_default(),
        sources: m.source_segments(),
        findings,
        variables: m
            .variables
            .iter()
            .map(|v| VariableView {
                name: v.name.clone(),
                value: v.value,
                expression: v.expression.clone(),
                tunable: v.tunable,
                comment: v.comment.clone(),
            })
            .collect(),
        unsolvable: m.program.as_ref().err().map(ToString::to_string),
        lowered: m.lowered,
        segmented_for: m.segmented_for,
        autoseg_log: m.autoseg_log.clone(),
        steprad_log: m.steprad_log.clone(),
    })
}

