/// The polarization of the far field in one direction.
#[derive(Serialize)]
pub struct PolarizationView {
    /// Vertical (θ) and horizontal (φ) gains, dBi.
    vertical: f64,
    horizontal: f64,
    /// Minor over major axis of the polarization ellipse: 0 linear, 1 circular.
    axial_ratio: f64,
    /// Tilt of the major axis from vertical, degrees.
    tilt: f64,
    /// "linear", "right" or "left" (hand), or "none" with no field.
    sense: &'static str,
}

impl From<&PatternPoint> for PolarizationView {
    fn from(p: &PatternPoint) -> Self {
        Self {
            vertical: p.vertical,
            horizontal: p.horizontal,
            axial_ratio: p.axial_ratio,
            tilt: p.tilt,
            sense: match p.sense {
                Sense::None => "none",
                Sense::Linear => "linear",
                Sense::Right => "right",
                Sense::Left => "left",
            },
        }
    }
}

