/// Solve a deck at `mhz` (or its first frequency), with its pattern, SWR against `z0`.
///
/// A deck whose last run writes a numerical Green's function (`WG`) has it computed and saved in
/// `store` first.
pub fn solve_at(
    text: &str,
    mhz: Option<f64>,
    z0: f64,
    store: &NgfStore,
    options: &ModelOptions,
) -> Result<SolveView, String> {
    let t0 = web_time::Instant::now();
    let m = model(text, store, &ModelOptions { mhz, ..*options })?;
    let prog = m.program().map_err(|e| e.to_string())?;
    let wrote_ngf = m.write_greens_function(store).map_err(|e| e.to_string())?;
    let f = match mhz {
        Some(v) => Frequency::from_mhz(v).map_err(|e| e.to_string())?,
        None => *prog
            .frequencies
            .first()
            .ok_or("the deck has no frequency")?,
    };
    let f = m.base.as_ref().map_or(f, |b| b.frequency);
    let sol = m.solve(f, prog.options(f)).map_err(|e| e.to_string())?;
    let pattern = if prog.sources.is_empty() {
        None
    } else {
        Some(pattern_view(prog, &m.geom, &sol))
    };
    Ok(SolveView {
        mhz: f.mhz(),
        // A 4nec2 current source reports the impedance at the segment it drives.
        inputs: m
            .source_inputs(&sol)
            .iter()
            .map(|i| InputView {
                segment: i.segment,
                tag: i.tag,
                z: [i.impedance.re, i.impedance.im],
                swr: swr(i.impedance, z0),
                power: i.power,
            })
            .collect(),
        currents: sol.currents.iter().map(|c| c.norm()).collect(),
        currents_complex: sol.currents.iter().map(|c| [c.re, c.im]).collect(),
        charges: sol.charge_densities().iter().map(|q| [q.re, q.im]).collect(),
        patch_currents: sol
            .patch_currents
            .iter()
            .map(|j| (j[0].norm_sqr() + j[1].norm_sqr() + j[2].norm_sqr()).sqrt())
            .collect(),
        wrote_ngf,
        antenna_z: m.matching.first().and_then(|(port1, _)| {
            let port2 = prog.networks.iter().find(|n| n.port1 == *port1)?.port2;
            let z = sol.network_ports.iter().find(|p| p.segment == port2 + 1)?.impedance;
            Some([z.re, z.im])
        }),
        power: PowerView {
            input: sol.power.input,
            radiated: sol.power.radiated(),
            structure_loss: sol.power.structure_loss,
            network_loss: sol.power.network_loss,
            efficiency: sol.power.efficiency_percent(),
        },
        pattern,
        millis: t0.elapsed().as_secs_f64() * 1e3,
    })
}

/// The model and its solution at `mhz` (the deck's first frequency when `None`; a numerical
/// Green's function's own when the run is built on one).
fn solved(text: &str, mhz: Option<f64>, store: &NgfStore, options: &ModelOptions) -> Result<(Model, Solution), String> {
    let m = model(text, store, &ModelOptions { mhz, ..*options })?;
    let prog = m.program().map_err(|e| e.to_string())?;
    let f = match mhz {
        Some(v) => Frequency::from_mhz(v).map_err(|e| e.to_string())?,
        None => *prog.frequencies.first().ok_or("the deck has no frequency")?,
    };
    let f = m.base.as_ref().map_or(f, |b| b.frequency);
    let sol = m.solve(f, prog.options(f)).map_err(|e| e.to_string())?;
    Ok((m, sol))
}

/// The near field on a slice of space.
pub fn near_field(
    text: &str,
    mhz: Option<f64>,
    req: &SliceRequest,
    store: &NgfStore,
    options: &ModelOptions,
) -> Result<Slice, String> {
    let (m, sol) = solved(text, mhz, store, options)?;
    m.near_field_slice(&sol, req).map_err(|e| e.to_string())
}

/// The NEC-style text report of the solution at `mhz`.
pub fn report(text: &str, mhz: Option<f64>, store: &NgfStore, options: &ModelOptions) -> Result<String, String> {
    let (m, sol) = solved(text, mhz, store, options)?;
    Ok(m.report(text, &sol))
}

/// `RP 0 nθ nφ XNDA θ0 φ0 dθ dφ` as a request.
fn request(
    n_theta: i32,
    n_phi: i32,
    xnda: i32,
    theta0: f64,
    phi0: f64,
    dtheta: f64,
    dphi: f64,
) -> PatternRequest {
    PatternRequest::from_fields(
        0,
        n_theta,
        n_phi,
        xnda,
        [theta0, phi0, dtheta, dphi, 0.0, 0.0],
    )
}

fn pattern_view(prog: &Program, geom: &Geometry, sol: &Solution) -> PatternView {
    let ground = prog.ground != GroundSpec::FreeSpace;
    let n_theta = if ground { 19 } else { 37 };
    // The full sphere (hemisphere over ground) on a 5° grid, with average gain.
    let grid = prog.pattern(geom, sol, &request(n_theta, 73, 1, 0.0, 0.0, 5.0, 5.0));
    let thetas: Vec<f64> = (0..n_theta).map(|i| 5.0 * f64::from(i)).collect();
    let phis: Vec<f64> = (0..73).map(|i| 5.0 * f64::from(i)).collect();
    let nt = thetas.len();
    let gain: Vec<Vec<f64>> = grid
        .points
        .chunks(nt)
        .map(|row| row.iter().map(|p| p.total).collect())
        .collect();
    let circular: Vec<(f64, f64)> = grid.points.iter().map(pattern::circular).collect();
    let rhcp: Vec<Vec<f64>> = circular.chunks(nt).map(|row| row.iter().map(|c| c.0).collect()).collect();
    let lhcp: Vec<Vec<f64>> = circular.chunks(nt).map(|row| row.iter().map(|c| c.1).collect()).collect();
    let strongest = |points: &[nec_solve::PatternPoint]| {
        points
            .iter()
            .max_by(|a, b| a.total.total_cmp(&b.total))
            .copied()
    };
    let coarse = strongest(&grid.points).expect("a pattern has points");
    // Refine to 1° around the coarse peak; directions below the ground are omitted.
    let fine = prog.pattern(
        geom,
        sol,
        &request(
            11,
            11,
            0,
            (coarse.theta - 5.0).max(0.0),
            coarse.phi - 5.0,
            1.0,
            1.0,
        ),
    );
    let peak = strongest(&fine.points)
        .filter(|p| p.total > coarse.total)
        .unwrap_or(coarse);

    // Fine cuts through the peak: azimuth at the peak's elevation (the horizon when the peak is
    // overhead), elevation in the vertical plane through the peak azimuth, front and back.
    let (azimuth_cut, elevation_cut) = pattern::cuts(prog, geom, sol, peak.theta, peak.phi);

    // Front-to-back against the back direction (4nec2's: the opposite azimuth over ground, the
    // opposite direction in free space), front-to-rear against the rear half of the grid.
    let (bt, bp) = pattern::back_direction(peak.theta, peak.phi, ground);
    let back_dir = prog.pattern(geom, sol, &request(1, 1, 0, bt, bp, 0.0, 0.0));
    let front_to_back = peak.total - back_dir.points.first().map_or(f64::NAN, |p| p.total);
    let front_to_rear =
        pattern::front_to_rear(peak.total, peak.theta, peak.phi, ground, &grid.points).unwrap_or(f64::NAN);
    let (peak_rhcp, peak_lhcp) = pattern::circular(&peak);
    PatternView {
        thetas,
        phis,
        gain,
        rhcp,
        lhcp,
        peak_gain: peak.total,
        peak_azimuth: peak.phi.rem_euclid(360.0),
        peak_elevation: 90.0 - peak.theta,
        polarization: PolarizationView::from(&peak),
        peak_rhcp,
        peak_lhcp,
        front_to_back,
        front_to_rear,
        average_gain: grid.average.map_or(f64::NAN, |a| a.0),
        azimuth_cut,
        elevation_cut,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const DIPOLE: &str =
        "CE\nGW 1 9 0 -.2418 0 0 .2418 0 .0001\nGE 0\nEX 0 1 5 0 1 0\nFR 0 1 0 0 300 0\nEN\n";

    #[test]
    fn a_dipole_analyzes_and_solves() {
        let a = analyze(DIPOLE, &NgfStore::default(), &ModelOptions::default()).expect("analyzes");
        assert_eq!(a.segments.len(), 9);
        assert!(a.unsolvable.is_none());
        let s = solve_at(DIPOLE, None, 50.0, &NgfStore::default(), &ModelOptions::default()).expect("solves");
        assert!((s.inputs[0].swr - 1.44).abs() < 0.01);
        assert!((s.inputs[0].z[0] - 72.08).abs() < 0.01);
        let p = s.pattern.expect("pattern");
        // A half-wave dipole: 2.15 dBi broadside, no front-to-back.
        assert!((p.peak_gain - 2.13).abs() < 0.05, "{}", p.peak_gain);
        assert!(p.front_to_back.abs() < 0.01);
    }
}
